-- PKG_DMF0043 — META 전환 확인 (조회 전용)
SET PAGESIZE 200 LINESIZE 300

-- DMF0043_GET_CONTRIBUTE_MAIN_DATA → PKG_DMF0043.P_DMF0043_GET_CONTRIBUTE_MAIN_DATA
SELECT API_ID, API_URL, CASE WHEN API_URL = 'PKG_DMF0043.P_DMF0043_GET_CONTRIBUTE_MAIN_DATA' THEN 'OK' ELSE 'NG' END CHK FROM SCM_MGR.SCM_ADM_API_M WHERE API_ID IN ('P_DMF0043_MAIN_GET');
SELECT 'PKG_DMF0043.P_DMF0043_GET_CONTRIBUTE_MAIN_DATA' PROC_NM,
       (SELECT COUNT(*) FROM SCM_MGR.SCM_ADM_PROC_M WHERE PROC_NM = 'PKG_DMF0043.P_DMF0043_GET_CONTRIBUTE_MAIN_DATA') NEW_ROWS,
       (SELECT COUNT(*) FROM SCM_MGR.SCM_ADM_PROC_M WHERE UPPER(PROC_NM) = 'DMF0043_GET_CONTRIBUTE_MAIN_DATA') STANDALONE_ROWS,
       (SELECT COUNT(*) FROM USER_ARGUMENTS WHERE PACKAGE_NAME = 'PKG_DMF0043' AND OBJECT_NAME = 'P_DMF0043_GET_CONTRIBUTE_MAIN_DATA' AND DATA_LEVEL = 0) MEMBER_ARGS,
       (SELECT LISTAGG(COL_TP_CD, ',') WITHIN GROUP (ORDER BY SORT_ORD) FROM SCM_MGR.SCM_ADM_PROC_M WHERE PROC_NM = 'PKG_DMF0043.P_DMF0043_GET_CONTRIBUTE_MAIN_DATA') PROC_M_INOUT,
       (SELECT LISTAGG(REPLACE(IN_OUT, 'IN/OUT', 'INOUT'), ',') WITHIN GROUP (ORDER BY POSITION) FROM USER_ARGUMENTS WHERE PACKAGE_NAME = 'PKG_DMF0043' AND OBJECT_NAME = 'P_DMF0043_GET_CONTRIBUTE_MAIN_DATA' AND DATA_LEVEL = 0) MEMBER_INOUT
  FROM DUAL;

